function maxPalindromes(s, k) {
  const n = s.length;
  let count = 0;
  let start = 0;

  for (let center = 0; center < 2 * n - 1; center++) {
    let left = Math.floor(center / 2);
    let right = left + (center % 2);

    while (left >= start && right < n && s[left] === s[right]) {
      if (right - left + 1 >= k) {
        count++;
        start = right + 1;
        break;
      }
      left--;
      right++;
    }
  }
  return count;
}

