function maxPalindromes(s, k) {
  const n = s.length;
  const isPalindrome = (from, to) => {
    const piece = s.slice(from, to);
    return piece === piece.split('').reverse().join('');
  };
  // most[i] = best answer using only the first i characters.
  const most = new Array(n + 1).fill(0);
  for (let i = 1; i <= n; i++) {
    most[i] = most[i - 1];
    for (let j = 0; j + k <= i; j++) {
      if (isPalindrome(j, i)) most[i] = Math.max(most[i], most[j] + 1);
    }
  }
  return most[n];
}

