function generate(rand, size) {
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const alphabet = letters.slice(0, 1 + Math.floor(rand() * (rand() < 0.7 ? 3 : 26)));
  const pick = () => alphabet[Math.floor(rand() * alphabet.length)];
  const n = size === 'large' ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 10);
  let s = '';
  while (s.length < n) {
    if (rand() < 0.3) {
      // Plant a palindrome so longer k values still find matches.
      const half = Array.from({ length: 1 + Math.floor(rand() * (size === 'large' ? 12 : 3)) }, pick).join('');
      s += half + (rand() < 0.5 ? pick() : '') + half.split('').reverse().join('');
    } else {
      s += pick();
    }
  }
  s = s.slice(0, n);
  const cap = size === 'large' ? Math.min(n, 30) : n;
  const k = rand() < 0.1 ? 1 + Math.floor(rand() * n) : 1 + Math.floor(rand() * cap);
  return [s, k];
}
